import{_ as s,l as n,o as e,c as t,v as i,p,x as o,d as l,i as m,S as d}from"./chunks/framework.InCnrqk-.js";const k=JSON.parse('{"title":"Lucas 定理","description":"","frontmatter":{"title":"Lucas 定理","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/lucas-theorem.md","filePath":"cs/lucas-theorem.md","lastUpdated":1789023840000}'),c={name:"cs/lucas-theorem.md"};function u(_,a,h,b,f,x){const r=n("Mermaid");return e(),t("div",null,[a[1]||(a[1]=i('<h1 id="lucas-定理" tabindex="-1">Lucas 定理 <a class="header-anchor" href="#lucas-定理" aria-label="Permalink to &quot;Lucas 定理&quot;">​</a></h1><div class="epigraph"><p>素数 $p$ 下，$\\binom{n}{m}\\equiv\\prod\\binom{n_i}{m_i}\\pmod p$，其中 $n_i,m_i$ 是 $p$ 进制数字；某位 $n_i\\lt m_i$ 则组合数为 0。</p><footer>—— 据 Lucas, Sur les congruences des nombres eulériens, 1878；初等数论教材整理</footer></div><p>上一课<a href="/cs/pollard-rho">Pollard rho</a>分解 \\(n\\)。组合数 \\(\\binom{n}{m}\\bmod p\\) 在 \\(n\\) 大、\\(p\\) 小素数时，不能先算阶乘。缺口是 Lucas：拆 \\(p\\) 进制。不重写 \\(\\varphi\\)。后课生成函数用形式幂级数，本课只要模 \\(p\\) 组合数。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>\\(n=\\sum n_i p^i\\)，\\(m=\\sum m_i p^i\\)，\\(0\\le n_i,m_i\\lt p\\)。Lucas：\\(\\binom{n}{m}\\equiv\\prod_i\\binom{n_i}{m_i}\\pmod p\\)。每位 \\(\\binom{n_i}{m_i}\\) 可 \\(O(p)\\) 或预处理阶乘表 \\(O(p)\\)。\\(n_i\\lt m_i\\) 则该位 0，整体 0。</p><p>缺口是进制拆，不是 Lucas 数列（同名不同）。模 \\(p^k\\) 要用更高（Kummer、Lucas 推广），本课点名。</p><h3 id="不是中国剩余定理本身" tabindex="-1">不是中国剩余定理本身 <a class="header-anchor" href="#不是中国剩余定理本身" aria-label="Permalink to &quot;不是中国剩余定理本身&quot;">​</a></h3><p>模合数 \\(M=\\prod p_i^{k}\\) 时，对每个 \\(p^k\\) 算组合数再 CRT。\\(k=1\\) 用本课；\\(k\\gt 1\\) 更重。不要只 Lucas 再 CRT 到 \\(p^2\\)。</p><p><span class="marginnote">Lucas 1878。Kummer 进位次数给 \\(p\\) 进赋值。后课生成函数 \\(\\sum\\binom n k x^k=(1+x)^n\\) 在形式幂级数，不取模。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>写 \\(n,m\\) 的 \\(p\\) 进制。预处理 \\(0..p-1\\) 的阶乘与逆元（<a href="/cs/euclid-extended">扩欧</a>）。逐位乘。\\(p\\) 不大。</p>',11)),(e(),p(d,null,{default:o(()=>[m(r,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20NM%5B%22n%2C%20m%20%E7%9A%84%20p%20%E8%BF%9B%E5%88%B6%22%5D%20--%3E%20BIN%5B%22%E5%90%84%E4%BD%8D%20C(n_i%2C%20m_i)%22%5D%0A%20%20BIN%20--%3E%20MOD%5B%22%E4%B9%98%E7%A7%AF%20mod%20p%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[l(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=i('<p>\\(p\\) 合数不能直接 Lucas。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>\\((1+x)^n=\\prod(1+x)^{n_i p^i}\\)，而 \\((1+x)^{p^i}\\equiv 1+x^{p^i}\\pmod p\\)（新鲜人的梦），展开对应各位独立选。与筛法无关。与 NTT：都用模 \\(p\\)，对象不同。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写 \\(q\\)-Lucas。不写大 \\(p\\) 的卢卡斯数列判素性（Lucas–Lehmer 是梅森数）。后课默认：\\(\\binom n m\\bmod p\\) 用 Lucas（\\(p\\) 小）。下一课生成函数。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>组合数模素数拆成各位小组合数。</li><li>某位不够则 0。</li><li>模素数幂要另法。</li><li>出处：Lucas, 1878。</li></ul>',7))])}const q=s(c,[["render",u]]);export{k as __pageData,q as default};
